-- Ported from Clashboard media-service (migrations/001_initial_schema.sql).
-- media_id is a deterministic SHA-1 UUID of "<provider>:<external_id>"
-- generated by the application, so the same item maps to the same row.
CREATE TABLE media (
    media_id         UUID PRIMARY KEY,
    external_id      VARCHAR(255) NOT NULL,
    provider         VARCHAR(50)  NOT NULL,
    title            VARCHAR(500) NOT NULL,
    description      TEXT,
    creator          VARCHAR(255),
    date             VARCHAR(50),
    thumbnail_url    VARCHAR(500),
    duration_seconds FLOAT8,
    download_status  VARCHAR(20) DEFAULT 'pending',
    local_path       TEXT,
    public_url       TEXT,
    file_size        BIGINT,
    mime_type        VARCHAR(100),
    imdb_rating      FLOAT8,
    actors           TEXT[],
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_media_external_id ON media (external_id);
CREATE INDEX idx_media_created_at ON media (created_at DESC);

CREATE TABLE media_comments (
    comment_id UUID PRIMARY KEY,
    media_id   UUID NOT NULL REFERENCES media (media_id) ON DELETE CASCADE,
    -- No FK to users yet: comments are still posted with a placeholder user
    -- until authentication (M1) lands. Add REFERENCES users (id) then.
    user_id    UUID NOT NULL,
    content    TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_media_comments_media_id ON media_comments (media_id);
CREATE INDEX idx_media_comments_user_id ON media_comments (user_id);
